const records = Array.isArray($json.records) ? $json.records : [];
return records.map(r => ({
  json: {
    airtable_record_id: r.id,
    ...r.fields
  }
}));

function toMillis(value) {
  if (!value) return null;
  const t = new Date(value).getTime();
  return Number.isFinite(t) ? t : null;
}

const matchWindowMinutes = Number($env.CLOVER_MATCH_WINDOW_MINUTES || 15);
const graceMinutes = Number($env.CLOVER_PENDING_GRACE_MINUTES || 10);
const orderDateMs = toMillis($json.order_date);
const now = Date.now();

if (!orderDateMs) {
  return {
    json: {
      ...$json,
      skip_reason: 'missing_order_date',
      shouldLookup: false
    }
  };
}

const amount = Number($json.order_total || 0);
const amountCents = Math.round(amount * 100);
const windowMs = matchWindowMinutes * 60 * 1000;
const graceMs = graceMinutes * 60 * 1000;

const start = orderDateMs - windowMs;
const end = orderDateMs + windowMs;
const ageMs = now - orderDateMs;

return {
  json: {
    ...$json,
    shouldLookup: amountCents > 0,
    order_date_ms: orderDateMs,
    order_total_num: amount,
    order_total_cents: amountCents,
    lookup_start_ms: start,
    lookup_end_ms: end,
    order_age_ms: ageMs,
    older_than_grace: ageMs > graceMs,
    clover_filter_start: `createdTime>=${start}`,
    clover_filter_end: `createdTime<=${end}`,
    reconciliation_debug: {
      airtable_record_id: $json.airtable_record_id,
      ecwid_order_id: $json.ecwid_order_id,
      order_number: $json.order_number,
      order_date: $json.order_date,
      order_total_cents: amountCents,
      lookup_start_ms: start,
      lookup_end_ms: end
    }
  }
};

const row = $('Code - Prepare Clover Lookup').item.json;
const paymentsResponse = $json || {};
const payments = Array.isArray(paymentsResponse.elements) ? paymentsResponse.elements : [];

const data = $getWorkflowStaticData('global');
const alreadyUsedIds = new Set(Array.isArray(data.cloverReconciliationUsedPaymentIds) ? data.cloverReconciliationUsedPaymentIds : []);
const reservedIds = new Set(Array.isArray(data.cloverReconciliationReservedPaymentIds) ? data.cloverReconciliationReservedPaymentIds : []);
const tenderMap = data.cloverReconciliationTenderMap || {};

const amountCents = Number(row.order_total_cents || 0);
const startMs = Number(row.lookup_start_ms || 0);
const endMs = Number(row.lookup_end_ms || 0);
const orderDateMs = Number(row.order_date_ms || 0);
const olderThanGrace = Boolean(row.older_than_grace);
const clearWinnerGapMs = Number($env.CLOVER_CLEAR_WINNER_GAP_MS || 60000);
const allowExternalAuto = String($env.CLOVER_AUTO_RECONCILE_EXTERNAL_PAYMENTS || '').toLowerCase() === 'true';
const assumeUnknownTenderCard = String($env.CLOVER_ASSUME_UNKNOWN_TENDERS_CARD || 'true').toLowerCase() !== 'false';
const configuredCardTenderIds = new Set(String($env.CLOVER_CARD_TENDER_IDS || '').split(',').map(s => s.trim()).filter(Boolean));
const configuredNonCardTenderIds = new Set(String($env.CLOVER_NON_CARD_TENDER_IDS || '').split(',').map(s => s.trim()).filter(Boolean));

function tenderInfo(p) {
  const id = String(p?.tender?.id || p?.tender || '').trim();
  const mapped = id && tenderMap[id] ? tenderMap[id] : {};
  const label = String(
    mapped.label ||
    p?.tender?.label ||
    p?.tender?.name ||
    p?.tender?.displayName ||
    ''
  ).trim();
  return {
    id: id || null,
    label: label || null,
    mapped: Boolean(mapped && (mapped.label || mapped.id))
  };
}

function isKnownNonCardTender(p) {
  const info = tenderInfo(p);
  const id = info.id || '';
  const label = String(info.label || '').toLowerCase();
  if (id && configuredNonCardTenderIds.has(id)) return true;
  if (!label) return false;
  return (
    label.includes('external') ||
    label.includes('cash') ||
    label.includes('check') ||
    label.includes('gift') ||
    label.includes('manual') ||
    label.includes('other')
  );
}

function isCardTender(p) {
  const info = tenderInfo(p);
  const id = info.id || '';
  const label = String(info.label || '').toLowerCase();

  if (id && configuredCardTenderIds.has(id)) return true;
  if (isKnownNonCardTender(p)) return false;

  if (label) {
    return label.includes('credit') || label.includes('debit') || label.includes('card');
  }

  // Clover payment objects often contain only tender.id unless tenders are fetched separately.
  // If we still cannot resolve the id, treat it as card by default so card sales do not all fall into needs_review.
  // Set CLOVER_ASSUME_UNKNOWN_TENDERS_CARD=false to make unknown tenders require review instead.
  return assumeUnknownTenderCard;
}

function selectedFields(p) {
  const info = tenderInfo(p);
  return {
    id: p?.id || null,
    order_id: p?.order?.id || null,
    amount_cents: p?.amount != null ? Number(p.amount) : null,
    created_ms: p?.createdTime != null ? Number(p.createdTime) : null,
    note: p?.note || p?.externalReferenceId || null,
    tender_id: info.id,
    tender_label: info.label || info.id || null,
  };
}

const amountTimeMatches = payments
  .filter((p) => {
    const createdMs = Number(p.createdTime || 0);
    const paymentAmount = Number(p.amount || 0);
    const result = String(p.result || '');
    const id = String(p.id || '');

    return (
      id &&
      result === 'SUCCESS' &&
      paymentAmount === amountCents &&
      createdMs >= startMs &&
      createdMs <= endMs
    );
  })
  .map((p) => {
    const createdMs = Number(p.createdTime || 0);
    const info = tenderInfo(p);
    const nonCard = isKnownNonCardTender(p);
    const card = isCardTender(p);
    return {
      ...p,
      _timeDistanceMs: Math.abs(createdMs - orderDateMs),
      _alreadyUsed: alreadyUsedIds.has(String(p.id || '')),
      _reservedThisRun: reservedIds.has(String(p.id || '')),
      _tenderId: info.id,
      _tenderLabel: info.label || info.id || '',
      _tenderMapped: info.mapped,
      _isKnownNonCardTender: nonCard,
      _isCardTender: card,
    };
  })
  .sort((a, b) => a._timeDistanceMs - b._timeDistanceMs);

const availableMatches = amountTimeMatches.filter(p => !p._alreadyUsed && !p._reservedThisRun);
const cardCandidates = availableMatches.filter(p => p._isCardTender || allowExternalAuto);
const nonCardCandidates = availableMatches.filter(p => !p._isCardTender && !allowExternalAuto);

let candidates = cardCandidates;
let match_action = 'pending';
let clover_candidate_count = candidates.length;
let clover_total_candidate_count = amountTimeMatches.length;
let clover_available_candidate_count = availableMatches.length;
let clover_non_card_candidate_count = nonCardCandidates.length;
let clover_selected_payment_id = null;
let clover_selected_order_id = null;
let clover_selected_amount_cents = null;
let clover_selected_created_ms = null;
let clover_selected_note = null;
let clover_selected_tender_id = null;
let clover_selected_tender_label = null;
let clover_match_confidence_num = null;
let reconciliation_note = 'No Clover payment found yet; keeping order pending.';

function choosePayment(p, action, confidence, note) {
  const s = selectedFields(p);
  match_action = action;
  clover_selected_payment_id = s.id;
  clover_selected_order_id = s.order_id;
  clover_selected_amount_cents = s.amount_cents;
  clover_selected_created_ms = s.created_ms;
  clover_selected_note = s.note;
  clover_selected_tender_id = s.tender_id;
  clover_selected_tender_label = s.tender_label;
  clover_match_confidence_num = confidence;
  reconciliation_note = note;

  if (s.id && (action === 'reconciled' || action === 'needs_review')) {
    reservedIds.add(String(s.id));
    data.cloverReconciliationReservedPaymentIds = [...reservedIds];
  }
}

if (candidates.length === 1) {
  choosePayment(
    candidates[0],
    'reconciled',
    1,
    'Matched single available card/allowed Clover payment by exact amount and closest createdTime within polling window.'
  );
} else if (candidates.length > 1) {
  const best = candidates[0];
  const second = candidates[1];
  const bestGap = Number(best._timeDistanceMs || 0);
  const secondGap = Number(second._timeDistanceMs || 0);

  if (secondGap - bestGap >= clearWinnerGapMs) {
    choosePayment(
      best,
      'reconciled',
      0.8,
      'Matched available card/allowed Clover payment by exact amount and closest createdTime within polling window; nearest candidate was clearly better than the next.'
    );
  } else {
    match_action = 'needs_review';
    reconciliation_note = 'Multiple available card/allowed Clover payments matched exact amount within polling window; no clear winner.';
  }
} else if (nonCardCandidates.length === 1) {
  choosePayment(
    nonCardCandidates[0],
    'needs_review',
    0.5,
    `Matched exact amount/time Clover payment, but tender is non-card (${nonCardCandidates[0]._tenderLabel || 'unknown'}); manual review required.`
  );
} else if (nonCardCandidates.length > 1) {
  match_action = 'needs_review';
  reconciliation_note = 'Only non-card/external Clover payments matched exact amount within polling window, and more than one candidate exists; manual review required.';
} else if (amountTimeMatches.length > 0 && availableMatches.length === 0) {
  match_action = 'needs_review';
  reconciliation_note = 'Clover payments matched amount/time, but all candidates were already used by prior reconciliations or reserved earlier in this workflow run; manual review required.';
} else {
  match_action = 'pending';
  reconciliation_note = olderThanGrace
    ? 'No Clover payment found yet; order remains pending for future polling.'
    : 'No Clover payment found yet; keeping order pending.';
}

return {
  json: {
    ...row,
    match_action,
    clover_candidate_count,
    clover_total_candidate_count,
    clover_available_candidate_count,
    clover_non_card_candidate_count,
    clover_selected_payment_id,
    clover_selected_order_id,
    clover_selected_amount_cents,
    clover_selected_created_ms,
    clover_selected_note,
    clover_selected_tender_id,
    clover_selected_tender_label,
    clover_match_confidence_num,
    reconciliation_note,
    reconciliation_debug: {
      ...(row.reconciliation_debug || {}),
      tender_map_count: Object.keys(tenderMap).length,
      used_payment_count: alreadyUsedIds.size,
      reserved_payment_count: reservedIds.size,
      total_amount_time_matches: amountTimeMatches.length,
      available_matches: availableMatches.length,
      card_candidates: cardCandidates.length,
      non_card_candidates: nonCardCandidates.length,
      candidate_ids: amountTimeMatches.map(p => ({
        id: p.id,
        amount: p.amount,
        createdTime: p.createdTime,
        tender_id: p._tenderId,
        tender: p._tenderLabel,
        tenderMapped: p._tenderMapped,
        isCardTender: p._isCardTender,
        isKnownNonCardTender: p._isKnownNonCardTender,
        alreadyUsed: p._alreadyUsed,
        reservedThisRun: p._reservedThisRun,
        timeDistanceMs: p._timeDistanceMs,
      }))
    }
  },
};

const status = $json.skip_reason ? 'needs_review' : 'pending';
const note = $json.skip_reason
  ? `Skipped Clover lookup: ${$json.skip_reason}`
  : 'Skipped Clover lookup.';

return {
  json: {
    ...$json,
    match_action: status,
    reconciliation_note: note,
    clover_candidate_count: 0,
    clover_selected_payment_id: null,
    clover_selected_order_id: null,
    clover_selected_amount_cents: null,
    clover_selected_created_ms: null,
    clover_selected_note: null,
    clover_selected_tender_id: null,
    clover_match_confidence_num: null
  }
};

function isoOrNull(ms) {
  if (!ms) return null;
  const d = new Date(Number(ms));
  return Number.isFinite(d.getTime()) ? d.toISOString() : null;
}

const nowIso = new Date().toISOString();
let status = $json.clover_reconciliation_status || 'pending';

if ($json.match_action === 'reconciled') status = 'reconciled';
else if ($json.match_action === 'needs_review') status = 'needs_review';
else if ($json.match_action === 'pending') status = 'pending';

const shouldKeepSelectedPayment = $json.match_action === 'reconciled' || $json.match_action === 'needs_review';

const fields = {
  clover_reconciliation_status: status,
  clover_payment_id: shouldKeepSelectedPayment ? ($json.clover_selected_payment_id || null) : null,
  clover_payment_amount:
    $json.clover_selected_amount_cents != null
      ? Number($json.clover_selected_amount_cents) / 100
      : null,
  clover_payment_time: isoOrNull($json.clover_selected_created_ms),
  clover_match_confidence: $json.clover_match_confidence_num,
  reconciled_at: $json.match_action === 'reconciled' ? nowIso : null,
  reconciliation_notes: [
    $json.reconciliation_note,
    $json.clover_total_candidate_count != null ? `Total candidates: ${$json.clover_total_candidate_count}` : null,
    $json.clover_available_candidate_count != null ? `Available candidates: ${$json.clover_available_candidate_count}` : null,
    $json.clover_non_card_candidate_count != null ? `Non-card candidates: ${$json.clover_non_card_candidate_count}` : null,
    $json.clover_selected_order_id ? `Clover order id: ${$json.clover_selected_order_id}` : null,
    $json.clover_selected_tender_id ? `Tender id: ${$json.clover_selected_tender_id}` : null,
    $json.clover_selected_tender_label ? `Tender: ${$json.clover_selected_tender_label}` : null,
    $json.clover_selected_note ? `Payment note: ${$json.clover_selected_note}` : null
  ].filter(Boolean).join(' | ')
};

return {
  json: {
    airtable_record_id: $json.airtable_record_id || null,
    ecwid_order_id: $json.ecwid_order_id || null,
    match_action: $json.match_action || 'pending',
    should_mark_ecwid_paid: $json.match_action === 'reconciled',
    clover_selected_payment_id: $json.clover_selected_payment_id || null,
    clover_selected_order_id: $json.clover_selected_order_id || null,
    reconciliation_debug: $json.reconciliation_debug || null,
    fields
  }
};

