const records = Array.isArray($json.records) ? $json.records : [];
const usedIds = records
  .map(r => String(r.fields?.clover_payment_id || '').trim())
  .filter(Boolean);

const data = $getWorkflowStaticData('global');
data.cloverReconciliationUsedPaymentIds = [...new Set(usedIds)];
data.cloverReconciliationReservedPaymentIds = [];
data.cloverReconciliationRunStartedAt = new Date().toISOString();

return {
  json: {
    used_clover_payment_ids: data.cloverReconciliationUsedPaymentIds,
    used_clover_payment_count: data.cloverReconciliationUsedPaymentIds.length,
    reserved_clover_payment_ids: []
  }
};

const tenders = Array.isArray($json.elements) ? $json.elements : [];
const tenderMap = {};

for (const t of tenders) {
  const id = String(t.id || '').trim();
  if (!id) continue;
  tenderMap[id] = {
    id,
    label: String(t.label || t.name || t.displayName || '').trim(),
    raw: t
  };
}

const data = $getWorkflowStaticData('global');
data.cloverReconciliationTenderMap = tenderMap;
data.cloverReconciliationTenderMapLoadedAt = new Date().toISOString();

return {
  json: {
    tender_count: Object.keys(tenderMap).length,
    tender_map: tenderMap
  }
};
